import {
  type CborValue,
  canonicalEncode,
  FIELD_REGISTRY,
  OBJECT_REGISTRY,
  type ProtocolObject,
  protocolObjectFromFields,
} from "@dotrelay/contracts";

const zeros = (length: number, fill = 0): Uint8Array =>
  new Uint8Array(length).fill(fill);

function fixtureValue(field: number): CborValue {
  const definition = FIELD_REGISTRY[field];
  if (!definition) throw new Error(`unknown vector field ${field}`);
  if (definition.type === "uint") {
    if (field === 35) return 1;
    if (field === 36) return 1;
    if (field === 37) return 1;
    if (field === 70) return 1;
    if (field === 78) return 1;
    if (field === 79) return 2;
    if (field === 71) return 0;
    if (field === 72) return 16;
    return 1;
  }
  if (definition.type === "array") return [];
  if (definition.type === "map") return new Map();
  if (definition.exactLength !== undefined)
    return zeros(definition.exactLength);
  if (field === 47) return zeros(16);
  return zeros(0);
}

function copyObject(object: ProtocolObject): ProtocolObject {
  return new Map(object);
}

export function buildVectorObject(
  kind: number,
  overrides: ReadonlyMap<number, CborValue> = new Map(),
): ProtocolObject {
  const definition = OBJECT_REGISTRY[kind];
  if (!definition) throw new Error(`unknown vector kind ${kind}`);
  const fields = new Map<number, CborValue>();
  for (const field of definition.requiredFields) {
    if (field > 2 && ![3, 4, 5, 6, 7].includes(field))
      fields.set(field, fixtureValue(field));
  }
  if (kind === 8) {
    fields.set(37, 2);
    fields.set(70, 3);
  }
  if (kind === 9) fields.set(70, 6);
  for (const [field, value] of overrides) fields.set(field, value);
  if (kind === 7 && fields.get(70) === 5 && !overrides.has(37))
    fields.set(37, 3);
  let object = protocolObjectFromFields(kind, fields);
  if (definition.serverVisible) {
    const unsigned = canonicalEncode(object);
    fields.set(3, unsigned);
    fields.set(4, zeros(3309, 0x11));
    fields.set(5, zeros(64, 0x22));
    if (kind === 3) {
      fields.set(6, zeros(3309, 0x33));
      fields.set(7, zeros(64, 0x44));
    }
    object = protocolObjectFromFields(kind, fields);
  }
  return copyObject(object);
}

export const VECTOR_CASES = Object.freeze([
  ...Array.from({ length: 19 }, (_, index) => ({
    id: `object-${index + 1}`,
    kind: index + 1,
    object: buildVectorObject(index + 1),
  })),
  ...Array.from({ length: 5 }, (_, index) => {
    const mutation = index + 1;
    const overrides = new Map<number, CborValue>([[35, mutation]]);
    if (mutation === 3) {
      overrides.set(21, zeros(16, 0x51));
      overrides.set(68, []);
    }
    return {
      id: `revision-mutation-${mutation}`,
      kind: 16,
      object: buildVectorObject(16, overrides),
    };
  }),
  ...Array.from({ length: 4 }, (_, index) => ({
    id: `lane-scope-${index + 1}`,
    kind: 13,
    object: buildVectorObject(13, new Map([[36, index + 1]])),
  })),
  ...(
    [
      [1, 7, 1],
      [2, 8, 2],
      [3, 7, 3, 5],
    ] as ReadonlyArray<readonly [number, number, number, number?]>
  ).map(([keyKind, kind, expectedKeyKind, grantKind]) => ({
    id: `key-kind-${keyKind}`,
    kind,
    object: buildVectorObject(
      kind,
      new Map<number, CborValue>(
        grantKind === undefined
          ? [[37, expectedKeyKind]]
          : [
              [37, expectedKeyKind],
              [70, grantKind],
            ],
      ),
    ),
  })),
  ...(
    [
      [1, 7],
      [2, 7],
      [3, 8],
      [4, 8],
      [5, 7],
      [6, 9],
      [7, 8],
    ] as ReadonlyArray<readonly [number, number]>
  ).map(([grantKind, kind]) => ({
    id: `grant-kind-${grantKind}`,
    kind,
    object: buildVectorObject(kind, new Map([[70, grantKind]])),
  })),
  ...Array.from({ length: 3 }, (_, index) => ({
    id: `membership-role-${index + 1}`,
    kind: 6,
    object: buildVectorObject(6, new Map([[78, index + 1]])),
  })),
  ...Array.from({ length: 6 }, (_, index) => ({
    id: `lifecycle-${index + 1}`,
    kind: 2,
    object: buildVectorObject(2, new Map([[79, index + 1]])),
  })),
]);

const hex = (value: string): Uint8Array =>
  Uint8Array.from(
    value.match(/../g)?.map((pair) => Number.parseInt(pair, 16)) ?? [],
  );

